92	class movetype::terrain_info::data
93	{
94	public:
95		/**
96		 * Constructor.
97		 * @a params must be long-lived (typically a static variable).
98		 */
99		explicit data(const parameters & params) :
100			cfg_(), cache_(), params_(params)
101		{}
