            "sources": [us("Spearman"), us("Pikeman"), us("Javelineer"), macro_src.get("WEAPON_SPECIAL_FIRSTSTRIKE", "未解析")],
        },
        {
            "title": "单位能力与机动：成本分母看不到治疗、照明、传送和防御态抗性",
