    ]
    edge_map = {(e["from"], e["to"]): e for e in data["edges"]}
    def edge_ev(a, b):
        e = edge_map[(a, b)]
        return f"{a}→{b}: HP {e['hp_from']}→{e['hp_to']}，movement {e['movement_from']}→{e['movement_to']}，cost {e['cost_from']}→{e['cost_to']}"
    data["test_questions"] = [
