    f = data["faction"]
    faction_rows = []
    for kind, ids, source in (("recruit", f["recruit_ids"], f["recruit_source"]), ("leader", f["leader_ids"], f["leader_source"]), ("random_leader", f["random_leader_ids"], f["random_leader_source"])):
        for uid in ids:
